mapper.select:
SELECT  FROM question_collection c
WHERE c.owner_id=#{owner} AND c.status=#{status}
AND c.kind=#{kind}
AND c.title LIKE #{pattern} ESCAPE '!'
AND c.id > #{cursor}
ORDER BY c.id LIMIT #{limit}

SELECT id,collection_id,owner_id,version_number,title,content_json,created_at
FROM question_collection_version
WHERE owner_id=#{owner} AND collection_id=#{collectionId} AND id=#{versionId}

SELECT id,version_number AS number,title,created_at FROM question_collection_version
WHERE owner_id=#{owner} AND collection_id=#{id}
AND version_number < #{before}
ORDER BY version_number DESC LIMIT #{limit}

mapper.update:
UPDATE question_collection SET title=#{title},current_version_id=#{versionId},version_number=#{number},
  step_count=#{stepCount},revision=revision+1,updated_at=#{now}
WHERE owner_id=#{owner} AND id=#{id} AND revision=#{expected}
